import numpy as np
from scipy.optimize import minimize

def objective(x):
    p, q, r, s = x
    return p/q + r/p + s/r + q/s

def constraint(x):
    p, q, r, s = x
    return (p + s) * (r + q) - (p * s + q * r)

# Since the problem is homogeneous, we can fix p = 1.
def objective_fixed_p(x):
    p = 1.0
    q, r, s = x
    return p/q + r/p + s/r + q/s

def constraint_fixed_p(x):
    p = 1.0
    q, r, s = x
    return (p + s) * (r + q) - (p * s + q * r)

# Let's try different starting points
best_f = float('inf')
for q_start in [0.1, 1, 10]:
    for r_start in [0.1, 1, 10]:
        for s_start in [0.1, 1, 10]:
            res = minimize(objective_fixed_p, [q_start, r_start, s_start],
                          constraints={'type': 'eq', 'fun': constraint_fixed_p},
                          bounds=[(1e-6, None), (1e-6, None), (1e-6, None)])
            if res.success and res.fun < best_f:
                best_f = res.fun
                best_x = res.x

print(f"Best f found: {best_f}")
print(f"Best x (q, r, s): {best_x}")

import numpy as np
from scipy.optimize import minimize

def objective(vars):
    k, m, x = vars
    return k + 1/(k*x) + m + x/m

def constraint(vars):
    k, m, x = vars
    return (k-1)*(m-1) - (k*x + m/x)

# We will try different starting points.
best_f = float('inf')
for k_s in [0.5, 2, 5]:
    for m_s in [0.5, 2, 5]:
        for x_s in [0.5, 1, 2]:
            res = minimize(objective, [k_s, m_s, x_s],
                          constraints={'type': 'eq', 'fun': constraint},
                          bounds=[(1e-6, None), (1e-6, None), (1e-6, None)])
            if res.success and res.fun < best_f:
                best_f = res.fun
                best_vars = res.x

print(f"Best f: {best_f}")
print(f"Best vars (k, m, x): {best_vars}")
